#include <bits/stdc++.h>
using namespace std;
int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    auto T0=chrono::steady_clock::now();
    auto elapsed=[&](){return chrono::duration<double>(chrono::steady_clock::now()-T0).count();};
    int N;cin>>N;
    vector<double>cx(N),cy(N);
    for(int i=0;i<N;i++)cin>>cx[i]>>cy[i];
    vector<bool>isp(max(N,2),false);
    {vector<bool>s(max(N,2),true);s[0]=s[1]=false;
    for(int i=2;(long long)i*i<N;i++)if(s[i])for(int j=i*i;j<N;j+=i)s[j]=false;
    for(int i=0;i<N;i++)isp[i]=s[i];}
    auto dd=[&](int a,int b)->double{double dx=cx[a]-cx[b],dy=cy[a]-cy[b];return sqrt(dx*dx+dy*dy);};
    auto gm=[&](int step,int src)->double{return(step%10==0&&!isp[src])?1.1:1.0;};
    auto ec=[&](int step,int f,int t)->double{return dd(f,t)*gm(step,f);};
    auto tourCost=[&](vector<int>&t)->double{double c=0;for(int s=1;s<=N;s++)c+=ec(s,t[s-1],t[s]);return c;};
    auto buildNN=[&](int sc)->vector<int>{
        vector<bool>vis(N,false);vector<int>t(N+1);
        t[0]=sc;vis[sc]=true;
        for(int step=1;step<N;step++){
            int last=t[step-1];int best=-1;double bd=1e30;
            for(int i=0;i<N;i++)if(!vis[i]){double d=dd(last,i);if(d<bd){bd=d;best=i;}}
            t[step]=best;vis[best]=true;
        }
        t[N]=sc;return t;
    };
    // For large N, use grid NN
    auto buildNNfast=[&](int sc)->vector<int>{
        double mx=1e18,Mx=-1e18,my=1e18,My=-1e18;
        for(int i=0;i<N;i++){mx=min(mx,cx[i]);Mx=max(Mx,cx[i]);my=min(my,cy[i]);My=max(My,cy[i]);}
        int gs=max(1,(int)sqrt((double)N/4.0));
        double cW=(Mx-mx)/gs+1e-9,cH=(My-my)/gs+1e-9;
        if(cW<1e-12)cW=1;if(cH<1e-12)cH=1;
        auto cell=[&](int i)->pair<int,int>{return{min(gs-1,max(0,(int)((cx[i]-mx)/cW))),min(gs-1,max(0,(int)((cy[i]-my)/cH)))};};
        auto idx=[&](int x,int y)->int{return y*gs+x;};
        vector<vector<int>>gr(gs*gs);
        for(int i=0;i<N;i++){auto[gx,gy]=cell(i);gr[idx(gx,gy)].push_back(i);}
        vector<bool>vis(N,false);vector<int>t(N+1);t[0]=sc;vis[sc]=true;
        {auto[gx,gy]=cell(sc);auto&v=gr[idx(gx,gy)];v.erase(find(v.begin(),v.end(),sc));}
        for(int step=1;step<N;step++){int last=t[step-1];auto[gx0,gy0]=cell(last);int best=-1;double bd=1e30;
        for(int rad=0;rad<=2*gs;rad++){if(best!=-1&&(double)(rad-1)*min(cW,cH)>bd*1.5)break;
        for(int dx=-rad;dx<=rad;dx++)for(int dy=-rad;dy<=rad;dy++){if(abs(dx)!=rad&&abs(dy)!=rad)continue;
        int gx=gx0+dx,gy=gy0+dy;if(gx<0||gx>=gs||gy<0||gy>=gs)continue;
        for(int id:gr[idx(gx,gy)])if(!vis[id]){double d=dd(last,id);if(d<bd){bd=d;best=id;}}}
        if(best!=-1&&rad>0)break;}
        t[step]=best;vis[best]=true;auto[gx,gy]=cell(best);auto&v=gr[idx(gx,gy)];v.erase(find(v.begin(),v.end(),best));}
        t[N]=sc;return t;
    };
    auto rot0=[&](vector<int>&t){int z=-1;for(int i=0;i<N;i++)if(t[i]==0){z=i;break;}
    if(z!=0){vector<int>r(N+1);for(int i=0;i<N;i++)r[i]=t[(z+i)%N];r[N]=0;t=r;}};
    vector<int>best;double bc=1e30;
    mt19937 rng(42);
    int tries=N<=5000?20:N<=20000?10:5;
    for(int tr=0;tr<tries&&elapsed()<1.0;tr++){
        int sc=tr==0?0:(int)(rng()%N);
        auto t=N<=5000?buildNN(sc):buildNNfast(sc);
        rot0(t);double c=tourCost(t);if(c<bc){bc=c;best=t;}
    }
    // pos[city] = index in tour (1..N-1 for interior, 0 and N are city 0)
    auto&T=best;double cc=bc;
    // Or-opt: relocate single city
    auto doRelocate=[&](){bool imp=true;while(imp&&elapsed()<1.85){imp=false;
    for(int i=1;i<N&&elapsed()<1.83;i++){
    double rem=ec(i,T[i-1],T[i])+ec(i+1,T[i],T[i+1])-ec(i,T[i-1],T[i+1]);// cost saved by removing T[i] (approx, step shifts)
    // try inserting T[i] at position j (after T[j-1], before T[j])
    int city=T[i];int wnd=min(N,200);
    double bestD=0;int bestJ=-1;
    for(int j=max(1,i-wnd);j<=min(N,i+wnd);j++){if(j==i||j==i+1)continue;
    // compute exact delta
    // Remove city from pos i, insert at pos j
    // This shifts positions - too complex for exact, use approximate
    double ins=ec(j,city,T[j])+ec(j,T[j-1],city)-ec(j,T[j-1],T[j]);// approx
    double delta=ins-rem;
    if(delta<bestD-1e-10){bestD=delta;bestJ=j;}}
    if(bestJ>=0){// do the move
    int c=T[i];T.erase(T.begin()+i);
    int j2=bestJ>i?bestJ-1:bestJ;
    T.insert(T.begin()+j2,c);
    cc=tourCost(T);imp=true;}}}};
    doRelocate();
    // Swap adjacent/nearby
    auto doSwap=[&](){bool imp=true;while(imp&&elapsed()<1.95){imp=false;
    for(int i=1;i<N&&elapsed()<1.93;i++){int wnd=min(N-1,100);
    for(int j=i+1;j<=min(N-1,i+wnd);j++){
    set<int>af;af.insert(i);af.insert(i+1);af.insert(j);af.insert(j+1);if(i>0)af.insert(i);
    // edges affected: i-1->i, i->i+1, j-1->j, j->j+1
    // if j==i+1: i-1->i, i->i+1, i+1->i+2
    double oC=0;set<int>steps;
    if(j==i+1){for(int s=i;s<=i+2&&s<=N;s++){oC+=ec(s,T[s-1],T[s]);steps.insert(s);}}
    else{for(int s=i;s<=i+1&&s<=N;s++){oC+=ec(s,T[s-1],T[s]);steps.insert(s);}
    for(int s=j;s<=j+1&&s<=N;s++){oC+=ec(s,T[s-1],T[s]);steps.insert(s);}}
    swap(T[i],T[j]);
    double nC=0;for(int s:steps)nC+=ec(s,T[s-1],T[s]);
    if(nC<oC-1e-10){cc+=nC-oC;imp=true;}else swap(T[i],T[j]);}}}};
    doSwap();
    cout<<N+1<<"\n";for(int i=0;i<=N;i++)cout<<T[i]<<"\n";
}
